const e="La mer ne demande pas d'où vous venez. Elle demande où vous allez.",t="Devise des marins d'Ikawora",n=["Peuple & Lignée","Elfes Maritimes","Codex #PEU-008"],a=[4,6,8],o="Ikawora, Archipels, Routes Maritimes",i="Navigation, Cartographie, Diplomatie",s="170cm - 195cm",r="280",l="« Elfe de la mer »",c="Umiyori_icone.jpeg",u="Commun",m=[{title:"Présentation",type:"text",content:"Les Umiyori sont la branche maritime des Elfes. Installés à Ikawora, ils ont orienté leur mode de vie vers la mer, le commerce neutre et l'exploration."},{title:"Rôle dans l'Âge des Explorations",type:"text",content:"Grâce à leur flotte et leur savoir cartographique, les Umiyori ont été les pionniers de la Première Traversée vers Nordheim et le Nouveau Monde."},{title:"Relations internationales",type:"politique_list_long",content:[{headline:"Amical / Protecteur",title:"Les Dra'Zuun",content:"Ont offert l'asile aux Dra'Zuun après la Rébellion, créant un havre cosmopolite.",color:"#34D399"},{headline:"Commercial",title:"Valm & Kovraks",content:"Maintiennent une neutralité marchande absolue avec l'ensemble des nations d'Asun.",color:"#34D399"}]},{title:"Aujourd'hui",type:"text",content:"Leurs navires continuent de sillonner l'ensemble des océans connus d'Asun."}],d={citation:e,citation_author:t,tags:n,link_articles:a,class:"Elfique",repart:o,trait:i,height:s,age:r,surname:l,image:c,statut:u,sections:m};export{r as age,e as citation,t as citation_author,d as default,s as height,c as image,a as link_articles,o as repart,m as sections,u as statut,l as surname,n as tags,i as trait};
